INSERT INTO `areaclic` VALUES ('mdCintura','Circunferncia da cintura','FITAMETRICA',NULL,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Circunfer\\\'eancia da cintura\\plain\\f3\\fs22 \r\n\\par \r\n\\par Para a circunfer\\\'eancia de cintura, a fita m\\\'e9trica dever\\\'e1 ser posicionada no plano horizontal, ao n\\\'edvel natural da cintura, isto \\\'e9, no ponto coincidente com a dist\\\'e2ncia m\\\'e9dia entre a \\\'faltima costela e a \\plain\\f3\\fs22\\ul crista-il\\\'edaca\\plain\\f3\\fs22 . A medida dever\\\'e1 ser obtida ao final de uma \\plain\\f3\\fs22\\ul expira\\\'e7\\\'e3o\\plain\\f3\\fs22  normal, sem a compress\\\'e3o da pele. O avaliador dever\\\'e1 postar-se \\\'e0 frente do avaliado.\r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',1);
INSERT INTO `areaclic` VALUES ('mdCircBraco','Circunferncia do brao','FITAMETRICA',NULL,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Circunfer\\\'eancia do bra\\\'e7o\r\n\\par \r\n\\par \\plain\\f3\\fs22 Deve ser medida com fita m\\\'e9trica inextens\\\'edvel no ponto m\\\'e9dio entre o acr\\\'f4mio da esc\\\'e1pula e o ol\\\'e9crano da ulna. Para a obten\\\'e7\\\'e3o desse ponto, o indiv\\\'edduo deve permanecer em p\\\'e9, com bra\\\'e7o fletido a 90\\\'ba e, com a fita, medir-se a dist\\\'e2ncia entre os 2 pontos citados acima, sendo que o ponto eq\\\'fcidistante deve ser marcado com uma caneta. Para se obter a CB, o indiv\\\'edduo deve relaxar o bra\\\'e7o e circundar o ser per\\\'edmetro com a fita, sem comprimir as partes moles. A leitura deve ser feita no cent\\\'edmetro mais pr\\\'f3ximo.\r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',8);
INSERT INTO `areaclic` VALUES ('mdCircPunho','Circunferncia do punho','FITAMETRICA',,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Circunfer\\\'eancia do punho\r\n\\par \r\n\\par \\plain\\f3\\fs22 A circunfer\\\'eancia do punho deve ser medida distalmente ao processo estil\\\'f3ide na dobra do punho, utilizando uma fita m\\\'e9trica inextens\\\'edvel.\r\n\\par \\pard\\plain\\f2\\fs16 \r\n\\par }\r\n',2);
INSERT INTO `areaclic` VALUES ('mdPBiceps','Prega cutnea do bceps','ADIPOMETRO',,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Prega cut\\\'e2nea do b\\\'edceps\\plain\\f3\\fs22 \r\n\\par \r\n\\par Deve ser medida na parte anterior do antebra\\\'e7o, sobre a maior eleva\\\'e7\\\'e3o do m\\\'fasculo b\\\'edceps, aplicando-se o adip\\\'f4metro a 1 cm abaixo dos dedos que pin\\\'e7avam a prega e, sem soltar, faz-se 3 leituras, utilizando a m\\\'e9dia das 2 mais pr\\\'f3ximas, no mil\\\'edmetro mais pr\\\'f3ximo.\r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',4);
INSERT INTO `areaclic` VALUES ('mdPSubescapular','Prega cutnea subescapular','ADIPOMETRO',,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Prega cut\\\'e2nea Subescapular\r\n\\par \\plain\\f3\\fs22 \r\n\\par Deve ser medida logo abaixo da extremidade da esc\\\'e1pula. A pele e o tecido subcut\\\'e2neo devem ser pin\\\'e7ados logo abaixo da borda da esc\\\'e1pula e a prega \\\'e9 angulada em 45\\\'ba a partir do plano horizontal,onde coloca-se o adip\\\'f4metro a 1 cm abaixo dos dedos que pin\\\'e7avam a prega e faz-se 3 leituras, utilizando-se a m\\\'e9dia das duas mais pr\\\'f3ximas, no mil\\\'edmetro mais pr\\\'f3ximo.\r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',5);
INSERT INTO `areaclic` VALUES ('mdPSuprailiaca','Prega cutnea suprailaca','ADIPOMETRO',,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Prega cut\\\'e2nea Suprail\\\'edaca\\plain\\f3\\fs22 \r\n\\par \r\n\\par Deve ser medida logo acima da crista il\\\'edaca, seguindo-se a linha axilar m\\\'e9dia. A pele e o tecido subcut\\\'e2neo devem ser pin\\\'e7ados e o adip\\\'f4metro aplicado a 1 cm dos dedos, e a leitura deve ser feita conforme descrito acima.\r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',6);
INSERT INTO `areaclic` VALUES ('mdPTriceps','Prega cutnea do trceps','ADIPOMETRO',,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Prega cut\\\'e2nea do tr\\\'edceps\\plain\\f3\\fs22 \r\n\\par \r\n\\par Deve ser medida na parte posterior do antebra\\\'e7o, sobre o m\\\'fasculo triciptal, no ponto m\\\'e9dio entre o acr\\\'f4mio e o ol\\\'e9crano, determinado da mesma maneira descrita para medir a CB. Estando o bra\\\'e7o relaxado, pin\\\'e7a-se a pele e o tecido subcut\\\'e2neo entre o polegar e o indicador e aplica-se o adip\\\'f4metro a 1 cm abaixo dos dedos que pin\\\'e7avam a prega e, sem soltar, faz-se 3 leituras, utilizando a m\\\'e9dia das 2 mais pr\\\'f3ximas, no mil\\\'edmetro mais pr\\\'f3ximo.\r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',7);
INSERT INTO `areaclic` VALUES ('mdPerimetroCefalico','Permetro Ceflico','FITAMETRICA',NULL,'{\\rtf1\\ansi\\deff0\\deflang1046{\\fonttbl{\\f0\\fswiss\\fprq2\\fcharset0 Arial;}{\\f1\\fswiss\\fprq2 Arial;}{\\f2\\fswiss MS Sans Serif;}}\r\n\\viewkind4\\uc1\\pard\\b\\f0\\fs22 Per\\\'edmetro Cef\\\'e1lico (PC)\\f1 \r\n\\par \\b0 \r\n\\par \\f0 Verificar com fita m\\\'e9trica flex\\\'edvel e inel\\\'e1stica. Deve-se manter a cabe\\\'e7a fixa e medir a circunfer\\\'eancia m\\\'e1xima colocando a fita sobre a regi\\\'e3o frontal e na proemin\\\'eancia do occipital, contornando a cabe\\\'e7a, ao mesmo n\\\'edvel, \\\'e0 direita e a esquerda.\\f1 \r\n\\par \r\n\\par Fonte: JELLIFFE, D.B. - \\ul\\f0 Evaluaci\\\'f3n del estado de nutrici\\\'f3n de la comunidad.\\ulnone\\f1  Ginebra, OMS, 1968. Figura 1.\r\n\\par \\f2\\fs16 \r\n\\par }\r\n',9);
INSERT INTO `areaclic` VALUES ('mdPerimetroToracico','Permetro Torcico','FITAMETRICA',NULL,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Per\\\'edmetro Tor\\\'e1cico (PT)\r\n\\par \\plain\\f3\\fs22 \r\n\\par Verificado com fita m\\\'e9trica flex\\\'edvel e inel\\\'e1stica. Passar a fita em torno do t\\\'f3rax, ao n\\\'edvel dos mamilos, sem comprimir as partes moles (tecidos) e se poss\\\'edvel, observando-se a leitura est\\\'e1 sendo feita durante a expira\\\'e7\\\'e3o ou inspira\\\'e7\\\'e3o. \r\n\\par \r\n\\par Fonte: JELLIFFE, D.B. \\endash  \\plain\\f3\\fs22\\ul Evaluaci\\\'f3n del estado de nutrici\\\'f3n de la comunidad.\\plain\\f3\\fs22  Ginebra, OMS, 1968. Figura 2.\r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',10);
INSERT INTO `areaclic` VALUES ('mdQuadril','Circunferncia do Quadril','FITAMETRICA',NULL,'{\\rtf1\\ansi\\deff0\\deftab720{\\fonttbl{\\f0\\fswiss MS Sans Serif;}{\\f1\\froman\\fcharset2 Symbol;}{\\f2\\fswiss\\fcharset1 MS Sans Serif;}{\\f3\\fswiss\\fprq2 Arial;}{\\f4\\fswiss\\fcharset1 MS Sans Serif;}}\r\n{\\colortbl\\red0\\green0\\blue0;}\r\n\\deflang1046\\pard\\plain\\f3\\fs22\\b Circunfer\\\'eancia do quadril\\plain\\f3\\fs22 \r\n\\par \r\n\\par Quanto a circunfer\\\'eancia do quadril, a fita m\\\'e9trica dever\\\'e1 ser posicionada horizontalmente ao n\\\'edvel dos gl\\\'fateos, na sua m\\\'e1xima circunfer\\\'eancia. O avaliador dever\\\'e1 postar-se \\\'e0 frente do avaliado.\r\n\\par \r\n\\par \\plain\\f4\\fs16 \r\n\\par }\r\n',3);